(async()=>{
if(plan===null)return;
const el=document.createElement('div');el.style.marginTop='20px';document.getElementById('pay').after(el);
const message=document.createElement('p');message.setAttribute('role','status');message.setAttribute('aria-live','polite');message.style.cssText='padding:16px;background:#eef4ff;border-radius:10px;white-space:pre-wrap';el.append(message);
const buttons=document.createElement('div');el.append(buttons);
const text=(zh,en)=>lang==='en'?en:zh;
let busy=false,orderID;try{
const config=await(await fetch('/api/paypal/config')).json();if(!config.enabled)return;
document.getElementById('pay').hidden=true;
function labels(){document.getElementById('notice').textContent=text('PayPal 沙箱测试：使用模拟资金，不会真实扣款。当前测试结算金额为 USD '+['2.49','6.49','19.99'][plan]+'，人民币价格不参与本次测试。','PayPal Sandbox: simulated funds only. Test checkout amount: USD '+['2.49','6.49','19.99'][plan]+'. No real payment.');document.getElementById('subtitle').textContent=text('确认套餐后，可使用 PayPal 测试买家账户付款。','Review your pack and pay using a PayPal sandbox buyer account.')}
labels();new MutationObserver(labels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
async function api(path,body){const {data}=await window.transpageSupabase.auth.getSession();if(!data.session)throw Error(text('请先登录，再返回此页面。','Please sign in, then return here.'));const r=await fetch('/api/paypal/'+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session.access_token},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(result.error);return result}
function success(credits){sessionStorage.removeItem('transpage_pending_payment');busy=false;buttons.hidden=true;message.style.background='#eaf7ee';message.textContent=text('支付成功！测试额度已到账：','Payment successful! Sandbox credits granted: ')+Number(credits).toLocaleString()+text(' 计费字符。',' billable characters.');document.getElementById('title').textContent=text('支付成功','Payment successful');retry.hidden=true;const link=document.createElement('a');link.href='account.html?v=payment';link.textContent=text('查看我的额度和购买记录 →','View my credits and purchases →');link.style.display='block';el.append(link);message.scrollIntoView({behavior:'smooth',block:'center'})}
async function capture(){if(busy)return;busy=true;retry.hidden=true;buttons.hidden=true;message.textContent=text('正在确认付款并发放额度，请稍候…','Confirming payment and granting credits…');message.scrollIntoView({behavior:'smooth',block:'center'});let error;for(let attempt=0;attempt<3;attempt++){try{const result=await api('capture',{orderID});success(result.credits);return}catch(e){error=e;if(attempt<2)await new Promise(r=>setTimeout(r,1500))}}busy=false;retry.hidden=false;message.textContent=text('付款结果尚未确认，请勿重复购买。点击下方重试确认，或前往账户页同步付款状态。\n','Payment not yet confirmed. Do not purchase again. Retry below or sync payments on your account page.\n')+error.message;throw error}
const retry=document.createElement('button');retry.hidden=true;retry.textContent=text('重试确认付款','Retry payment confirmation');retry.onclick=async()=>{retry.disabled=true;try{await capture()}catch(e){message.textContent=e.message}finally{retry.disabled=false}};el.append(retry);
await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(config.clientId)+'&currency=USD&intent=capture';s.onload=resolve;s.onerror=reject;document.head.append(s)});
await paypal.Buttons({createOrder:async()=>{message.textContent=text('正在创建测试订单…','Creating test order…');const result=await api('create',{plan});orderID=result.id;sessionStorage.setItem('transpage_pending_payment',JSON.stringify({orderID,plan}));return result.id},onApprove:async data=>{orderID=data.orderID;try{await capture()}catch{}},onCancel:()=>{sessionStorage.removeItem('transpage_pending_payment');message.textContent=text('已取消测试付款。','Test payment cancelled.')},onError:e=>{message.textContent=e.message||text('测试支付失败，请重试。','Test payment failed. Please retry.')}}).render(buttons);
async function recover(){if(busy||!orderID)return;try{const result=await api('sync',{});if(result.updated){await capture()}}catch{}}
window.addEventListener('focus',recover);
const saved=sessionStorage.getItem('transpage_pending_payment');if(saved){try{const pending=JSON.parse(saved);if(pending.plan===plan){orderID=pending.orderID;retry.hidden=false;message.textContent=text('检测到尚未确认的订单，可点击重试确认付款。','An unconfirmed order was found. Retry payment confirmation below.');recover()}}catch{}}
}catch(e){message.textContent=e.message||text('PayPal 加载失败，请刷新重试。','Could not load PayPal. Refresh to retry.')}
})();
